public void testAclWithUnNaturalOrder() {
    AclEntity ae = accessService.getAclEntity(AclEntityType.PROJECT_INSTANCE, "1eaca32a-a33e-4b69-83dd-0bb8b1f8c91b");
    // read from metadata
    MutableAclRecord acl = accessService.getAcl(ae);
    // order by sid_order in aceImpl
