    val groups = userGroupService.getUserGroupsFilterByGroupName("G");
    Assert.assertEquals(3, groups.size());
    for (val group : groups) {
        Assert.assertNotNull(group.getUuid());
        Assert.assertTrue(group.getGroupName().contains("g"));
