    userGroupService.modifyGroupUsers("g2", Lists.newArrayList("u2", "u4", "u6"));
    checkResult();
    userGroupService.modifyGroupUsers("g1", Lists.newArrayList("u3", "u5"));
    Assert.assertEquals(Lists.newArrayList(new SimpleGrantedAuthority(GROUP_ALL_USERS)), userService.loadUserByUsername("u1").getAuthorities());
    //test delete
    Assert.assertEquals(Lists.newArrayList(new SimpleGrantedAuthority(GROUP_ALL_USERS), new SimpleGrantedAuthority("g1")), userService.loadUserByUsername("u3").getAuthorities());
    Assert.assertEquals(Lists.newArrayList(new SimpleGrantedAuthority(GROUP_ALL_USERS), new SimpleGrantedAuthority("g1")), userService.loadUserByUsername("u5").getAuthorities());
    userGroupService.deleteGroup("g1");
    Assert.assertEquals(Lists.newArrayList(new SimpleGrantedAuthority(GROUP_ALL_USERS)), userService.loadUserByUsername("u3").getAuthorities());
    Assert.assertEquals(Lists.newArrayList(new SimpleGrantedAuthority(GROUP_ALL_USERS)), userService.loadUserByUsername("u5").getAuthorities());
    Map<String, List<String>> result = userGroupService.getUserAndUserGroup();
    Assert.assertEquals(2, result.size());
    Assert.assertEquals(9, result.get("user").size());
    Assert.assertEquals(2, result.get("group").size());
    Assert.assertEquals("g2", result.get("group").get(0));
    Assert.assertEquals("g3", result.get("group").get(1));
}

