public void testQueryHistoryAccelerateRunner() {
    long startTime = System.currentTimeMillis();
    val internalExecute = Lists.<Long>newArrayList();
    val mockSleepTimeSecs = 1;
    val mockSchedulerDelay = 2;
    val queryHistoryAccelerateRunnerMock = qhAccelerateScheduler.new QueryHistoryAccelerateRunner(false) {

        @Override
        public void work() {
            await().pollDelay(mockSleepTimeSecs, TimeUnit.SECONDS).until(() -> {
                internalExecute.add((System.currentTimeMillis() - startTime) / 1000);
                //mock exception
                throw new RuntimeException("test for exception");
            });
        }
    };
    val queryHistoryMetaUpdateRunnerMock = qhAccelerateScheduler.new QueryHistoryMetaUpdateRunner() {

        @Override
        public void work() {
            await().pollDelay(mockSleepTimeSecs, TimeUnit.SECONDS);
        }
    };
    ReflectionTestUtils.setField(qhAccelerateScheduler, "taskScheduler", Executors.newScheduledThreadPool(1, new NamedThreadFactory("QueryHistoryWorker(project:" + PROJECT + ")")));
    try {
        val schedulerService = (ScheduledExecutorService) ReflectionTestUtils.getField(qhAccelerateScheduler, "taskScheduler");
        Assert.assertNotNull(schedulerService);
        schedulerService.scheduleWithFixedDelay(queryHistoryAccelerateRunnerMock, 0, mockSchedulerDelay, TimeUnit.SECONDS);
        schedulerService.scheduleWithFixedDelay(queryHistoryMetaUpdateRunnerMock, 0, mockSchedulerDelay, TimeUnit.SECONDS);
        val schedulerNum = 10;
        await().pollDelay(schedulerNum, TimeUnit.SECONDS).until(() -> {
            Assert.assertEquals(internalExecute.size(), schedulerNum / (mockSchedulerDelay + mockSleepTimeSecs));
            for (int i = 0; i < internalExecute.size(); i++) {
                Assert.assertEquals(internalExecute.get(i), i * mockSchedulerDelay + mockSleepTimeSecs * (i + 1), 1);
            }
            return null;
        });
    } catch (Exception e) {
        log.error("test qhAccelerateScheduler error :", e);
    } finally {
        QueryHistoryTaskScheduler.shutdownByProject(PROJECT);
    }
}

