    getTestConfig().setProperty("kylin.security.acl.data-permission-default-enabled", "false");
    if (!userService.userExists("ADMIN1")) {
        userService.createUser(new ManagedUser("ADMIN1", "ADMIN1", false, //
        Arrays.//
        asList(new SimpleGrantedAuthority(Constant.ROLE_ADMIN))));
    }
    if (!userService.userExists("ADMIN2")) {
        userService.createUser(new ManagedUser("ADMIN2", "ADMIN2", false, //
        Arrays.//
        asList(new SimpleGrantedAuthority(Constant.ROLE_ADMIN))));
    }
    GlobalBatchAccessRequest globalBatchAccessRequest = new GlobalBatchAccessRequest();
    globalBatchAccessRequest.setUsernameList(Arrays.asList("ADMIN1", "ADMIN2"));
    userAclService.grantUserAclPermission(globalBatchAccessRequest, "DATA_QUERY");
    Assert.assertTrue(userAclService.hasUserAclPermission("ADMIN1", AclPermission.DATA_QUERY));
    Assert.assertTrue(userAclService.hasUserAclPermission("ADMIN2", AclPermission.DATA_QUERY));
}

@Test
public void testBasics() {
    userService.deleteUser("MODELER");
    Assert.assertTrue(!userService.userExists("MODELER"));
    List<GrantedAuthority> authorities = new ArrayList<GrantedAuthority>();
    authorities.add(new SimpleGrantedAuthority(Constant.ROLE_ADMIN));
    ManagedUser user = new ManagedUser("MODELER", "PWD", false, authorities);
    userService.createUser(user);
    Assert.assertTrue(userService.userExists("MODELER"));
    Assert.assertTrue(userAclService.hasUserAclPermission("MODELER", AclPermission.DATA_QUERY));
    UserDetails ud = userService.loadUserByUsername("MODELER");
    Assert.assertEquals("MODELER", ud.getUsername());
    Assert.assertEquals("PWD", ud.getPassword());
    Assert.assertEquals(Constant.ROLE_ADMIN, ud.getAuthorities().iterator().next().getAuthority());
    Assert.assertEquals(2, ud.getAuthorities().size());
    userService.deleteUser("MODELER");
    Assert.assertFalse(userAclService.hasUserAclPermission("MODELER", AclPermission.DATA_QUERY));
}

