@Test
void testQueryNodeAuditLogCatchup(JdbcInfo jdbcInfo) {
    KylinConfig kylinConfig = getTestConfig();
    val resourceStore = ResourceStore.getKylinMetaStore(kylinConfig);
    resourceStore.checkAndPutResource("/UUID", new StringEntity(RandomUtil.randomUUIDStr()), StringEntity.serializer);
    Assertions.assertEquals(1, resourceStore.listResourcesRecursively("/").size());
    val url = getTestConfig().getMetadataUrl();
    val jdbcTemplate = jdbcInfo.getJdbcTemplate();
    String unitId = RandomUtil.randomUUIDStr();
    // write 3 msg to audit log
    jdbcTemplate.batchUpdate(String.format(Locale.ROOT, JdbcAuditLogStore.INSERT_SQL, url.getIdentifier() + "_audit_log"), Arrays.asList(new Object[] { "/_global/project/abc1", "abc".getBytes(charset), System.currentTimeMillis(), 0, unitId, null, LOCAL_INSTANCE }, new Object[] { "/_global/project/abc2", "abc".getBytes(charset), System.currentTimeMillis(), 0, unitId, null, LOCAL_INSTANCE }, new Object[] { "/_global/project/abc3", "abc".getBytes(charset), System.currentTimeMillis(), 0, unitId, null, LOCAL_INSTANCE }));
    // no catchup, so resourceStore.offset = 0
    Assertions.assertEquals(0, resourceStore.getOffset());
    ((JdbcAuditLogStore) resourceStore.getAuditLogStore()).forceClose();
    // mock another ke query node start and catchup audit log
    KylinConfig queryConfig = KylinConfig.createKylinConfig(kylinConfig);
    queryConfig.setProperty("kylin.server.mode", "query");
    queryConfig.setProperty("kylin.server.store-type", "jdbc");
    val queryResourceStore = ResourceStore.getKylinMetaStore(queryConfig);
    // queryResourceStore.offset must be 3
    Assertions.assertEquals(3, queryResourceStore.getOffset());
    val auditLogStore = queryResourceStore.getAuditLogStore();
    val replayWorker = (AuditLogReplayWorker) ReflectionTestUtils.getField(auditLogStore, "replayWorker");
    Assertions.assertNotNull(replayWorker);
    Assertions.assertEquals(0, replayWorker.getLogOffset());
    val mockWorker = Mockito.spy(replayWorker);
    Mockito.doNothing().when(mockWorker).catchupToMaxId(Mockito.anyLong());
    ReflectionTestUtils.setField(auditLogStore, "replayWorker", mockWorker);
    queryResourceStore.getMetadataStore().setAuditLogStore(auditLogStore);
    // mock catchup, Make sure replay Auditlog is not executed
    queryResourceStore.catchup();
    Assertions.assertEquals(3, ((JdbcAuditLogStore) queryResourceStore.getMetadataStore().getAuditLogStore()).replayWorker.getLogOffset());
    jdbcTemplate.batchUpdate(String.format(Locale.ROOT, JdbcAuditLogStore.INSERT_SQL, url.getIdentifier() + "_audit_log"), Arrays.asList(new Object[] { "/_image", "{\"offset\":5}".getBytes(charset), System.currentTimeMillis(), 0, unitId, null, LOCAL_INSTANCE }, new Object[] { "/_global/project/abc4", "abc".getBytes(charset), System.currentTimeMillis(), 0, unitId, null, LOCAL_INSTANCE }));
    // Make sure replay auditlog is executed
    ReflectionTestUtils.setField(auditLogStore, "replayWorker", replayWorker);
    queryResourceStore.getMetadataStore().setAuditLogStore(auditLogStore);
    // catchup '/_image' metadata
    queryResourceStore.catchup();
    // catchup offset from '/_image'
    queryResourceStore.catchup();
    Assertions.assertEquals(5, ((JdbcAuditLogStore) queryResourceStore.getMetadataStore().getAuditLogStore()).replayWorker.getLogOffset());
    ((JdbcAuditLogStore) queryResourceStore.getAuditLogStore()).forceClose();
}

@Test
public void testVerify(@TempDir File junitFolder) throws Exception {
    //copy an metadata image to junit folder
    ResourceTool.copy(getTestConfig(), KylinConfig.createInstanceFromUri(junitFolder.getAbsolutePath()), "/_global/project/default.json");
    ResourceTool.copy(getTestConfig(), KylinConfig.createInstanceFromUri(junitFolder.getAbsolutePath()), "/default");
    getTestConfig().setMetadataUrl(junitFolder.getAbsolutePath());
    val metadataStore = MetadataStore.createMetadataStore(getTestConfig());
    MetadataChecker metadataChecker = new MetadataChecker(metadataStore);
    //add illegal file,the verify result is not qualified
    Paths.get(junitFolder.getAbsolutePath(), "/IllegalFile").toFile().createNewFile();
    val verifyResultWithIllegalFile = metadataChecker.verify();
    Assertions.assertThat(verifyResultWithIllegalFile.getIllegalFiles()).hasSize(1).contains("/IllegalFile");
    assertFalse(verifyResultWithIllegalFile.isQualified());
    Paths.get(junitFolder.getAbsolutePath(), "/IllegalFile").toFile().delete();
    //add illegal project dir ,the verify result is not qualified
    Paths.get(junitFolder.getAbsolutePath(), "/IllegalProject").toFile().mkdir();
    Paths.get(junitFolder.getAbsolutePath(), "/IllegalProject/test.json").toFile().createNewFile();
    val verifyResultWithIllegalProject = metadataChecker.verify();
    Assertions.assertThat(verifyResultWithIllegalProject.getIllegalProjects()).hasSize(1).contains("IllegalProject");
    Assertions.assertThat(verifyResultWithIllegalProject.getIllegalFiles()).hasSize(1).contains("/IllegalProject/test.json");
    assertFalse(verifyResultWithIllegalProject.isQualified());
    Paths.get(junitFolder.getAbsolutePath(), "/IllegalProject/test.json").toFile().delete();
    Paths.get(junitFolder.getAbsolutePath(), "/IllegalProject").toFile().delete();
    //add legal project and file,the verify result is qualified
    Paths.get(junitFolder.getAbsolutePath(), "/legalProject").toFile().mkdir();
    Paths.get(junitFolder.getAbsolutePath(), "/_global").toFile().mkdir();
    Paths.get(junitFolder.getAbsolutePath(), "/_global/project").toFile().mkdir();
    Paths.get(junitFolder.getAbsolutePath(), "/_global/project/legalProject.json").toFile().createNewFile();
    val verifyResultWithLegalProject = metadataChecker.verify();
    Assertions.assertThat(verifyResultWithLegalProject.getIllegalFiles()).isEmpty();
    Assertions.assertThat(verifyResultWithLegalProject.getIllegalProjects()).isEmpty();
    assertTrue(verifyResultWithLegalProject.isQualified());
    //the metadata dir doesn't have uuid file
    assertFalse(metadataChecker.verify().isExistUUIDFile());
    Paths.get(junitFolder.getAbsolutePath(), "/UUID").toFile().createNewFile();
    assertTrue(metadataChecker.verify().isExistUUIDFile());
    //the metadata dir doesn't have user group file
    assertFalse(metadataChecker.verify().isExistUserGroupFile());
    Files.createFile(Paths.get(junitFolder.getAbsolutePath(), "/_global/user_group"));
    assertTrue(metadataChecker.verify().isExistUserGroupFile());
    //the metadata dir doesn't have user dir
    assertFalse(metadataChecker.verify().isExistUserDir());
    Paths.get(junitFolder.getAbsolutePath(), "/_global/user").toFile().mkdir();
    Files.createFile(Paths.get(junitFolder.getAbsolutePath(), "/_global/user/ADMIN"));
    assertTrue(metadataChecker.verify().isExistUserDir());
    //the metadata dir doesn't have acl dir
    assertFalse(metadataChecker.verify().isExistACLDir());
    Paths.get(junitFolder.getAbsolutePath(), "/_global/acl").toFile().mkdir();
    Files.createFile(Paths.get(junitFolder.getAbsolutePath(), "/_global/acl/test"));
    assertTrue(metadataChecker.verify().isExistACLDir());
}

