@OverwriteProp(key = "kylin.server.mode", value = "query")
@Test
public void testKE19979() throws InterruptedException {
    AtomicInteger mvcc = new AtomicInteger(0);
    val initEvent = new ResourceCreateOrUpdateEvent(new RawResource("/default/abc.json", ByteSource.wrap("version1".getBytes(charset)), 0L, mvcc.get()));
    val synchronize = MessageSynchronization.getInstance(getTestConfig());
    synchronize.replayInTransaction(new UnitMessages(Lists.newArrayList(initEvent)));
    val resourceStore = ResourceStore.getKylinMetaStore(getTestConfig());
    val loopTime = 1000;
    val starter = new CountDownLatch(1);
    val latch1 = new CountDownLatch(loopTime);
    val latch2 = new CountDownLatch(loopTime);
    AtomicInteger nullCount = new AtomicInteger(0);
    Thread t1 = new Thread(new Runnable() {

        @SneakyThrows
        @Override
        public void run() {
            starter.await();
            while (latch1.getCount() > 0) {
                val updateEvent = new ResourceCreateOrUpdateEvent(new RawResource("/default/abc.json", ByteSource.wrap("version2".getBytes(charset)), 0L, mvcc.incrementAndGet()));
                synchronize.replayInTransaction(new UnitMessages(Lists.newArrayList(updateEvent)));
                latch1.countDown();
            }
        }
    });
    Thread t2 = new Thread(new Runnable() {

        @SneakyThrows
        @Override
        public void run() {
            starter.await();
            while (latch2.getCount() > 0) {
                if (null == resourceStore.getResource("/default/abc.json")) {
                    nullCount.incrementAndGet();
                }
                latch2.countDown();
            }
        }
    });
    t1.start();
    t2.start();
    starter.countDown();
    latch1.await();
    latch2.await();
    Assert.assertEquals(0, nullCount.get());
}

@Test
public void testStravition() {
    val threads = Lists.<LogicThread>newArrayList();
    for (int i = 0; i < 10; i++) {
        val t = new LogicThread(i % 4 != 0);
        t.start();
        threads.add(t);
    }
    Awaitility.await().atMost(2, TimeUnit.MINUTES).until(() -> threads.stream().map(t -> t.getCount() > 10).reduce(true, (l, r) -> l && r));
    long maxCount = threads.stream().mapToLong(LogicThread::getCount).max().getAsLong();
    long minCount = threads.stream().mapToLong(LogicThread::getCount).min().getAsLong();
    Assert.assertTrue(maxCount - minCount <= 1);
    TransactionLock.projectLocks = Maps.newConcurrentMap();
    for (LogicThread thread : threads) {
        thread.interrupt();
    }
}

