    new Thread(() -> {
        try {
            epochMgr.updateAllEpochs();
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            cdl.countDown();
        }
    }).start();
    new Thread(() -> {
        try {
            epochMgrCopy.updateAllEpochs();
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            cdl.countDown();
        }
    }).start();
    cdl.await(10, TimeUnit.SECONDS);
