        Assert.assertNotEquals(new JoinDescNonEquiCompBean(supplierSimpleJoinDesc.apply(cond1)), new JoinDescNonEquiCompBean(supplierSimpleJoinDesc.apply(cond2)));
    }
    //equal
    {
        NonEquiJoinCondition cond1 = nonEquiMock.composite(SqlKind.EQUALS, nonEquiMock.colOp("abs", SqlKind.OTHER_FUNCTION, "A.a9"), nonEquiMock.colOp("abs", SqlKind.OTHER_FUNCTION, "B.a9"));
        NonEquiJoinCondition cond2 = nonEquiMock.composite(SqlKind.EQUALS, nonEquiMock.colOp("abs", SqlKind.OTHER_FUNCTION, "B.a9"), nonEquiMock.colOp("abs", SqlKind.OTHER_FUNCTION, "A.a9"));
        Assert.assertEquals(new JoinDescNonEquiCompBean(supplierSimpleJoinDesc.apply(cond1)), new JoinDescNonEquiCompBean(supplierSimpleJoinDesc.apply(cond2)));
    }
    //equal
    {
        NonEquiJoinCondition cond1 = nonEquiMock.composite(SqlKind.AND, nonEquiMock.colCompareCond(SqlKind.EQUALS, "A.a8", "B.b8"), nonEquiMock.composite(SqlKind.NOT, nonEquiMock.colCompareCond(SqlKind.EQUALS, "A.a9", "B.b9")), nonEquiMock.composite(SqlKind.NOT, nonEquiMock.colOp(SqlKind.IS_NULL, "A.a9")), nonEquiMock.colCompareCond(SqlKind.LESS_THAN_OR_EQUAL, "A.a1", "B.b1"), nonEquiMock.colCompareCond(SqlKind.LESS_THAN, "A.a4", "B.b4"));
        NonEquiJoinCondition cond2 = nonEquiMock.composite(SqlKind.AND, nonEquiMock.colCompareCond(SqlKind.EQUALS, "B.b8", "A.a8"), nonEquiMock.colCompareCond(SqlKind.NOT_EQUALS, "B.b9", "A.a9"), nonEquiMock.colOp(SqlKind.IS_NOT_NULL, "A.a9"), nonEquiMock.composite(SqlKind.NOT, nonEquiMock.colCompareCond(SqlKind.GREATER_THAN, "A.a1", "B.b1")), nonEquiMock.composite(SqlKind.NOT, nonEquiMock.colCompareCond(SqlKind.GREATER_THAN_OR_EQUAL, "A.a4", "B.b4")));
        Assert.assertEquals(new JoinDescNonEquiCompBean(supplierSimpleJoinDesc.apply(cond1)), new JoinDescNonEquiCompBean(supplierSimpleJoinDesc.apply(cond2)));
    }
}

