@Test
public void testAddNonCustomProjectConfigs() {
    NProjectManager projectManager = NProjectManager.getInstance(getTestConfig());
    projectManager.updateProject("default", update_project -> {
        LinkedHashMap<String, String> overrideKylinProps = update_project.getOverrideKylinProps();
        overrideKylinProps.put("kylin.query.implicit-computed-column-convert", "false");
    });
    {
        val project = projectManager.getProject("default");
        Assert.assertEquals("false", project.getConfig().getExtendedOverrides().get("kylin.query.implicit-computed-column-convert"));
    }
    {
        val projectInstance = new ProjectInstance();
        projectInstance.setName("override_setting");
        val project = projectManager.getProject("default");
        projectInstance.setOverrideKylinProps((LinkedHashMap<String, String>) project.getConfig().getExtendedOverrides());
        Assert.assertEquals("false", projectInstance.getOverrideKylinProps().get("kylin.query.implicit-computed-column-convert"));
    }
    {
        getTestConfig().setProperty("kylin.server.non-custom-project-configs", "kylin.query.implicit-computed-column-convert");
        projectManager.reloadAll();
        val project = projectManager.getProject("default");
        Assert.assertEquals("false", project.getOverrideKylinProps().get("kylin.query.implicit-computed-column-convert"));
        Assert.assertNull(project.getLegalOverrideKylinProps().get("kylin.query.implicit-computed-column-convert"));
        Assert.assertNull(project.getConfig().getExtendedOverrides().get("kylin.query.implicit-computed-column-convert"));
    }
}

