@Test
@SuppressWarnings("checkstyle:methodlength")
public void testConvertSqlWithEscape() throws SQLException, SqlParseException {
    DataSourceDefProvider provider = DataSourceDefProvider.getInstance();
    ConvMaster master = new ConvMaster(provider.getDefault(), provider.getById(TEST_TARGET));
    SqlConverter converter = new SqlConverter(new SqlConverter.IConfigurer() {

        @Override
        public boolean useUppercaseDefault() {
            return true;
        }

        @Override
        public boolean allowNoOffset() {
            return true;
        }

        @Override
        public boolean allowFetchNoRows() {
            return true;
        }

        @Override
        public boolean allowNoOrderByWithFetch() {
            return true;
        }

        @Override
        public boolean enableCache() {
            return true;
        }

        @Override
        public boolean enableQuote() {
            return true;
        }

        @Override
        public String getTransformDatePattern() {
            return null;
        }
    }, master);
    // normal cases
    Assert.assertEquals("SELECT 1", converter.convertSql("select     1"));
    Assert.assertEquals("SELECT *\nFROM \"FACT\"", converter.convertSql("select * from FACT"));
    // limit and offset
    Assert.assertEquals("SELECT 1\nFETCH NEXT 1 ROWS ONLY", converter.convertSql("SELECT 1 LIMIT 1"));
    Assert.assertEquals("SELECT 1\nFETCH NEXT 0 ROWS ONLY", converter.convertSql("SELECT 1 LIMIT 0"));
    Assert.assertEquals("SELECT 1\nOFFSET 1 ROWS\nFETCH NEXT 1 ROWS ONLY", converter.convertSql("SELECT 1 LIMIT 1 OFFSET 1"));
    // escape default keywords
    Assert.assertEquals("SELECT *\nFROM \"DEFAULT\".\"FACT\"", converter.convertSql("select * from DEFAULT.FACT"));
    Assert.assertEquals("SELECT *\nFROM \"DEFAULT\".\"FACT\"", converter.convertSql("select * from \"DEFAULT\".FACT"));
    Assert.assertEquals("SELECT *\nFROM \"DEFAULT\".\"FACT\"", converter.convertSql("select * from \"Default\".FACT"));
    Assert.assertEquals("SELECT *\nFROM \"DEFAULT\".\"FACT\"", converter.convertSql("select * from \"default\".FACT"));
    // function mapping
    Assert.assertEquals("SELECT EXTRACT(DOY FROM \"PART_DT\")\nFROM \"DEFAULT\".\"FACT\"", converter.convertSql("select DAYOFYEAR(PART_DT) from \"DEFAULT\".FACT"));
    Assert.assertEquals("SELECT 12 * (EXTRACT(YEAR FROM \"DT1\") - EXTRACT(YEAR FROM \"DT2\")) + EXTRACT(MONTH FROM \"DT1\") - EXTRACT(MONTH FROM \"DT2\") - " + "CASE WHEN EXTRACT(DAY FROM \"DT2\") > EXTRACT(DAY FROM \"DT1\") THEN 1 ELSE 0 END\n" + "FROM \"DEFAULT\".\"FACT\"", converter.convertSql("select TIMESTAMPDIFF(month,DT2,      DT1) from \"DEFAULT\".FACT"));
    Assert.assertEquals("SELECT TRUNC(\"ID\")\nFROM \"DEFAULT\".\"FACT\"", converter.convertSql("select cast(ID as INT) from \"DEFAULT\".FACT"));
    Assert.assertEquals("SELECT 1\nFROM \"A\"\nWHERE 1 BETWEEN 0 AND 2", converter.convertSql("select 1 from a where 1 BETWEEN 0 and 2"));
    Assert.assertEquals("SELECT \"CURRENT_DATE\", TEST_CURR_TIME()", converter.convertSql("select CURRENT_DATE, CURRENT_TIME"));
    Assert.assertEquals("SELECT EXP(AVG(LN(EXTRACT(DOY FROM CAST('2018-03-20' AS DATE)))))\nFROM \"DEFAULT\".\"FACT\"", converter.convertSql("select exp(avg(ln(dayofyear(cast('2018-03-20' as date))))) from \"DEFAULT\".FACT"));
    // over function
    Assert.assertEquals("SELECT STDDEVP(\"C1\") OVER (ORDER BY \"C1\")\nFROM \"TEST_SUITE\"\nFETCH NEXT 1 ROWS ONLY", converter.convertSql("select stddev_pop(c1) over(order by c1) from test_suite limit 1"));
    // type mapping
    Assert.assertEquals("SELECT CAST(\"PRICE\" AS DOUBLE PRECISION)\nFROM \"DEFAULT\".\"FACT\"", converter.convertSql("select cast(PRICE as DOUBLE) from \"DEFAULT\".FACT"));
    Assert.assertEquals("SELECT CAST(\"PRICE\" AS DECIMAL(19, 4))\nFROM \"DEFAULT\".\"FACT\"", converter.convertSql("select cast(PRICE as DECIMAL(19,4)) from \"DEFAULT\".FACT"));
    Assert.assertEquals("SELECT CAST(\"PRICE\" AS DECIMAL(19))\nFROM \"DEFAULT\".\"FACT\"", converter.convertSql("select cast(PRICE as DECIMAL(19)) from \"DEFAULT\".FACT"));
    Assert.assertEquals("SELECT CAST(\"BYTE\" AS BIT(8))\nFROM \"DEFAULT\".\"FACT\"", converter.convertSql("select cast(BYTE as BYTE) from \"DEFAULT\".FACT"));
    Assert.assertEquals("SELECT CAST(\"BYTE\" AS VARCHAR(1024))\nFROM \"DEFAULT\".\"FACT\"", converter.convertSql("select cast(BYTE as VARCHAR(1024)) from \"DEFAULT\".FACT"));
    // cannot find mapping
    Assert.assertEquals("SELECT \"CURRENT_DATE_1\", \"CURRENT_TIME_1\"", converter.convertSql("select CURRENT_DATE_1, CURRENT_TIME_1"));
    Assert.assertEquals("SELECT \"CURRENT_DATE_1\", TEST_CURR_TIME(), \"CURRENT_DATE\"", converter.convertSql("select CURRENT_DATE_1, CURRENT_TIME, CURRENT_DATE"));
    Assert.assertEquals("SELECT CAST(\"BYTE\" AS VAR(1024))\nFROM \"DEFAULT\".\"FACT\"", converter.convertSql("select cast(BYTE as VAR(1024)) from \"DEFAULT\".FACT"));
    Assert.assertEquals("SELECT CAST(\"PRICE\" AS DDD)\nFROM \"DEFAULT\".\"FACT\"", converter.convertSql("select cast(PRICE as DDD) from \"DEFAULT\".FACT"));
    Assert.assertEquals("SELECT A(), B(\"A\"), CAST(\"PRICE\" AS DDD)\nFROM \"DEFAULT\".\"FACT\"", converter.convertSql("select A(), B(A), cast(PRICE as DDD) from \"DEFAULT\".\"FACT\""));
    Assert.assertEquals("SELECT ONLY_DEFAULT(1)", converter.convertSql("SELECT ONLY_DEFAULT(1)"));
    // invalid case
    Assert.assertEquals("create table test(id int, price double, name string, value byte)", converter.convertSql("create table test(id int, price double, name string, value byte)"));
    Assert.assertEquals("select cast(BYTE as VARCHAR(1000000000000)) from \"DEFAULT\".FACT", converter.convertSql("select cast(BYTE as VARCHAR(1000000000000)) from \"DEFAULT\".FACT"));
    Assert.assertEquals("I am not a SQL", converter.convertSql("I am not a SQL"));
}

