            List<String> cacheTables = instance.getTables(PROJECT, DATABASE);
            return !cacheTables.isEmpty();
        });
    } catch (Exception e) {
        // ignore
    }
    thread2.interrupt();
    getTestConfig().setProperty("kylin.kerberos.project-level-enabled", "false");
