    projectManager.updateProject(projectInstance, projectInstanceUpdate.getName(), projectInstanceUpdate.getDescription(), projectInstanceUpdate.getOverrideKylinProps());
    instance.run();
    List<String> cacheTables2 = instance.getTables(PROJECT, DATABASE);
    Assert.assertFalse(cacheTables2.isEmpty());
}

