    Assert.assertEquals("18,Shenzhen,1", r3.get(0));
    Assert.assertEquals("19,Beijing,2", r3.get(1));
    Assert.assertEquals("20,Shanghai,1", r3.get(2));
    String query4 = "select AGE, CITY, intersect_count(USER_ID, TAG, array['handsome']) " + "from TEST_INTERSECT_COUNT group by AGE, CITY";
    List<String> r4 = ExecAndComp.queryModel(getProject(), query4).collectAsList().stream().map(row -> row.toSeq().mkString(",")).collect(Collectors.toList());
    Assert.assertEquals("18,Shenzhen,1", r4.get(0));
    Assert.assertEquals("19,Beijing,1", r4.get(1));
    Assert.assertEquals("20,Shanghai,2", r4.get(2));
    String query5 = "select AGE, CITY, intersect_count(USER_ID, TAG, array['rich', 'tall']) " + "from TEST_INTERSECT_COUNT group by AGE, CITY";
    List<String> r5 = ExecAndComp.queryModel(getProject(), query5).collectAsList().stream().map(row -> row.toSeq().mkString(",")).collect(Collectors.toList());
    Assert.assertEquals("18,Shenzhen,0", r5.get(0));
    Assert.assertEquals("19,Beijing,1", r5.get(1));
