    List<String> r6 = ExecAndComp.queryModel(getProject(), query6).collectAsList().stream().map(row -> row.toSeq().mkString(",")).collect(Collectors.toList());
    Assert.assertEquals("Beijing,1", r6.get(0));
    Assert.assertEquals("Shanghai,1", r6.get(1));
    Assert.assertEquals("Shenzhen,0", r6.get(2));
}

