@Test
public void testSimilarToEscapeFunction() throws Exception {
    fullBuild("9cde9d25-9334-4b92-b229-a00f49453757");
    populateSSWithCSVData(getTestConfig(), getProject(), SparderEnv.getSparkSession());
    List<String> result;
    String query1 = "SELECT count(*) FROM TEST_MEASURE where NAME1 SIMILAR TO 'Ch.na'";
    result = ExecAndComp.queryModel(getProject(), query1).collectAsList().stream().map(row -> row.toSeq().mkString(",")).collect(Collectors.toList());
    Assert.assertEquals("3", result.get(0));
    String query2 = "SELECT count(*) FROM TEST_MEASURE where NAME1 SIMILAR TO 'Ch@_na' ESCAPE '@'";
    result = ExecAndComp.queryModel(getProject(), query2).collectAsList().stream().map(row -> row.toSeq().mkString(",")).collect(Collectors.toList());
    Assert.assertEquals("1", result.get(0));
    String query3 = "SELECT count(*) FROM TEST_MEASURE where NAME1 SIMILAR TO 'Ch%%na' ESCAPE '%'";
    result = ExecAndComp.queryModel(getProject(), query3).collectAsList().stream().map(row -> row.toSeq().mkString(",")).collect(Collectors.toList());
    Assert.assertEquals("1", result.get(0));
    result.remove(0);
    try {
        String query4 = "SELECT count(*) FROM TEST_MEASURE where NAME1 SIMILAR TO 'Ch@.na' ESCAPE '@@'";
        result = ExecAndComp.queryModel(getProject(), query4).collectAsList().stream().map(row -> row.toSeq().mkString(",")).collect(Collectors.toList());
    } catch (Exception e) {
        Assert.assertEquals("0", String.valueOf(result.size()));
    }
    String query5 = "SELECT count(*) FROM TEST_MEASURE where NAME1 SIMILAR TO 'Ch@%na' ESCAPE '@'";
    result = ExecAndComp.queryModel(getProject(), query5).collectAsList().stream().map(row -> row.toSeq().mkString(",")).collect(Collectors.toList());
    Assert.assertEquals("1", result.get(0));
    String query6 = "SELECT count(*) FROM TEST_MEASURE where NAME1 SIMILAR TO 'Ch%na' ESCAPE '~'";
    result = ExecAndComp.queryModel(getProject(), query6).collectAsList().stream().map(row -> row.toSeq().mkString(",")).collect(Collectors.toList());
    Assert.assertEquals("1", result.get(0));
}

