    String sqlWithPlaceholder = sqlOrign.replace("where TEST_ORDER.TEST_TIME_ENC='2013-01-01 12:02:11' ", "where TEST_ORDER.TEST_TIME_ENC=? ");
    List<Row> rows = ExecAndComp.queryModel(getProject(), sqlWithPlaceholder, Arrays.asList(new Timestamp[] { Timestamp.valueOf(paramString) })).collectAsList();
    List<List<String>> setTimestampResults = transformToString(rows);
    // setTimestamp pushdown
    PrepareSqlStateParam[] params = new PrepareSqlStateParam[] { new PrepareSqlStateParam(Timestamp.class.getCanonicalName(), paramString) };
    String sqlPushDown = PrepareSQLUtils.fillInParams(sqlWithPlaceholder, params);
    List<List<String>> setTimestampPushdownResults = SparkSqlClient.executeSql(ss, sqlPushDown, RandomUtil.randomUUID(), getProject()).getFirst();
    // setString
    List<Row> rows2 = ExecAndComp.queryModel(getProject(), sqlWithPlaceholder, Arrays.asList(new String[] { paramString })).collectAsList();
    List<List<String>> setStringResults = transformToString(rows2);
    // setString pushdown
    PrepareSqlStateParam[] params2 = new PrepareSqlStateParam[] { new PrepareSqlStateParam(String.class.getCanonicalName(), paramString) };
    String sqlPushDown2 = PrepareSQLUtils.fillInParams(sqlWithPlaceholder, params2);
    List<List<String>> setStringPushdownResults = SparkSqlClient.executeSql(ss, sqlPushDown2, RandomUtil.randomUUID(), getProject()).getFirst();
    Assert.assertEquals(benchmark.size(), setTimestampResults.size());
    Assert.assertEquals(benchmark.size(), setTimestampPushdownResults.size());
    Assert.assertEquals(benchmark.size(), setStringResults.size());
    Assert.assertEquals(benchmark.size(), setStringPushdownResults.size());
    for (int i = 0; i < benchmark.size(); i++) {
        if (!ListUtils.isEqualList(benchmark.get(i), setTimestampResults.get(i)) && !ListUtils.isEqualList(benchmark.get(i), setTimestampPushdownResults.get(i)) && !ListUtils.isEqualList(benchmark.get(i), setStringResults.get(i)) && !ListUtils.isEqualList(benchmark.get(i), setStringPushdownResults.get(i))) {
            String expected = Strings.join(benchmark.get(i), ",");
            String actual1 = Strings.join(setTimestampResults.get(i), ",");
            String actual2 = Strings.join(setTimestampPushdownResults.get(i), ",");
            String actual3 = Strings.join(setStringResults.get(i), ",");
            String actual4 = Strings.join(setStringPushdownResults.get(i), ",");
            fail("expected: " + expected + ", setTimestampResults: " + actual1 + ", setTimestampPushdownResults: " + actual2 + ", setStringResults: " + actual3 + ", setStringPushdownResults: " + actual4);
        }
    }
}

