    Assert.assertEquals(12, indexPlan.getAllLayouts().size());
    // should 6, rule based black layout should be deleted
    Assert.assertEquals(7, indexPlan.getRuleBaseLayouts().size());
    Assert.assertEquals(5, indexPlan.getWhitelistLayouts().size());
    // 2 recommendation agg index
    Assert.assertEquals(2, indexPlan.getWhitelistLayouts().stream().filter(layoutEntity -> !layoutEntity.isManual()).filter(layoutEntity -> IndexEntity.isAggIndex(layoutEntity.getId())).count());
    // 2 recommendation table index
    Assert.assertEquals(2, indexPlan.getWhitelistLayouts().stream().filter(layoutEntity -> !layoutEntity.isManual()).filter(layoutEntity -> IndexEntity.isTableIndex(layoutEntity.getId())).count());
    // 1
    Assert.assertEquals(1, indexPlan.getWhitelistLayouts().stream().filter(LayoutEntity::isManual).filter(layoutEntity -> IndexEntity.isTableIndex(layoutEntity.getId())).count());
}

