    // new layout id
    val newLayoutId = indexPlanManager.getIndexPlan(modelId).getAllLayouts().stream().filter(l -> l.getColOrder().containsAll(newIndexCol)).findFirst().map(LayoutEntity::getId).orElse(-2L);
    Assert.assertTrue(newLayoutId > oldLayoutId);
}

