@Test
public void testUpdateSegmentConfigWhenError() {
    val project = PROJECT;
    val segmentConfigRequest = new SegmentConfigRequest();
    segmentConfigRequest.setAutoMergeEnabled(false);
    segmentConfigRequest.setAutoMergeTimeRanges(Collections.singletonList(AutoMergeTimeEnum.DAY));
    segmentConfigRequest.getRetentionRange().setRetentionRangeType(null);
    try {
        projectService.updateSegmentConfig(project, segmentConfigRequest);
        Assert.fail();
    } catch (Exception e) {
        Assert.assertTrue(e instanceof KylinException);
        Assert.assertTrue(e.getMessage().contains("No valid value for 'retention_range_type', Please set {'DAY', 'MONTH', 'YEAR'} to specify the period of retention."));
    }
    segmentConfigRequest.getVolatileRange().setVolatileRangeNumber(-1);
    try {
        projectService.updateSegmentConfig(project, segmentConfigRequest);
        Assert.fail();
    } catch (Exception e) {
        Assert.assertTrue(e instanceof KylinException);
        Assert.assertTrue(e.getMessage().contains("No valid value. Please set an integer 'x' to " + "'volatile_range_number'. The 'Auto-Merge' will not merge latest 'x' " + "period(day/week/month/etc..) segments."));
    }
    segmentConfigRequest.getVolatileRange().setVolatileRangeNumber(1);
    segmentConfigRequest.getRetentionRange().setRetentionRangeNumber(-1);
    try {
        projectService.updateSegmentConfig(project, segmentConfigRequest);
        Assert.fail();
    } catch (Exception e) {
        Assert.assertTrue(e instanceof KylinException);
        Assert.assertTrue(e.getMessage().contains("No valid value for 'retention_range_number'." + " Please set an integer 'x' to specify the retention threshold. The system will " + "only retain the segments in the retention threshold (x years before the last data time). "));
    }
    segmentConfigRequest.getRetentionRange().setRetentionRangeNumber(1);
    segmentConfigRequest.setAutoMergeTimeRanges(new ArrayList<>());
    try {
        projectService.updateSegmentConfig(project, segmentConfigRequest);
        Assert.fail();
    } catch (Exception e) {
        Assert.assertTrue(e instanceof KylinException);
        Assert.assertTrue(e.getMessage().contains("No valid value for 'auto_merge_time_ranges'. Please set " + "{'DAY', 'WEEK', 'MONTH', 'QUARTER', 'YEAR'} to specify the period of auto-merge. "));
    }
}

