    String contents = StringUtils.join(Files.readAllLines(new File("src/test/resources/ut_meta/case_sensitive/table_desc/CASE_SENSITIVE.TEST_KYLIN_FACT.json").toPath(), Charset.defaultCharset()), "\n");
