@Test
public void testMoreTimestampAddAndDiff() {
    String originSql, ccSql;
    originSql = "select sum((int1-int2)/(int1+int2)) as c1,\n" + "sum((int1-int2)/timestampdiff(second, time0, time1) ) as c2,\n" + "sum(timestampdiff(second, time0, time1)/timestampdiff(second, timestampadd(year,1, time1), time1)) as c3\n" + "from tdvt.calcs";
    ccSql = //
    "select sum(CALCS.CC_AUTO_4) as c1,\n" + //
    "sum(CALCS.CC_AUTO_5 ) as c2,\n" + //
    "sum(CALCS.CC_AUTO_18) as c3\n" + "from tdvt.calcs";
    check(converter, originSql, ccSql, "tdvt");
    // case 2
    originSql = "select sum(case when int0 > 0 then timestampdiff(day, time0, time1) end) as ab\n" + "  from tdvt.calcs as calcs";
    ccSql = "select sum(CALCS.CC_AUTO_11) as ab\n  from tdvt.calcs as calcs";
    check(converter, originSql, ccSql, "tdvt");
    // case 3
    originSql = "select sum(case when time0 <> time1 then (int2-int1)/timestampdiff(second, time0, time1) * 60\n" + //
    "    else (int2 - int1)/ timestampdiff(second, time1, datetime0)*60 end)\n" + "from tdvt.calcs";
    ccSql = "select sum(CALCS.CC_AUTO_6)\nfrom tdvt.calcs";
    check(converter, originSql, ccSql, "tdvt");
    // case 4
    originSql = "select case when int0 > 0 then timestampdiff(second, time0, time1) else 0 end\n" + "from tdvt.calcs\n" + "group by case when int0 > 0 then timestampdiff(second, time0, time1) else 0 end\n" + "order by case when int0 > 0 then timestampdiff(second, time0, time1) else 0 end";
    ccSql = //
    "select CALCS.CC_AUTO_29\n" + //
    "from tdvt.calcs\n" + //
    "group by CALCS.CC_AUTO_29\n" + "order by CALCS.CC_AUTO_29";
    check(converter, originSql, ccSql, "tdvt");
    // case 5
    originSql = "select case when int0 > 100 then timestampdiff(second, time0, time1)\n" + "                when int0 > 50 then timestampdiff(minute, time0, time1)\n" + "                when int0 > 0 then timestampdiff(hour, time0, time1) else null end\n" + "from tdvt.calcs group by case when int0 > 100 then timestampdiff(second, time0, time1)\n" + "                when int0 > 50 then timestampdiff(minute, time0, time1)\n" + "                when int0 > 0 then timestampdiff(hour, time0, time1) else null end";
    ccSql = "select CALCS.CC_AUTO_31\nfrom tdvt.calcs group by CALCS.CC_AUTO_31";
    check(converter, originSql, ccSql, "tdvt");
    // case 6
    originSql = "select case when int0 > 10 then sum(timestampdiff(second, time0, time1)) else sum(timestampdiff(minute, time0, time1)) end\n" + "from tdvt.calcs group by int0";
    ccSql = "select case when int0 > 10 then sum(CALCS.CC_AUTO_38) else sum(CALCS.CC_AUTO_1) end\n" + "from tdvt.calcs group by int0";
    check(converter, originSql, ccSql, "tdvt");
    // case 7: will not replace
    originSql = "with ca as(select time0 as t0, time1, datetime0 from tdvt.calcs)\n" + "select sum(timestampdiff(minute, ca.time1, ca.t0)), ca.datetime0\n" + "from ca group by ca.datetime0";
    ccSql = "with ca as(select time0 as t0, time1, datetime0 from tdvt.calcs)\n" + "select sum(timestampdiff(minute, ca.time1, ca.t0)), ca.datetime0\n" + "from ca group by ca.datetime0";
    check(converter, originSql, ccSql, "tdvt");
    // case 8
    originSql = "select sum(tmp.ab) from (\n" + "  select sum(timestampdiff(second, time0, time1)/timestampdiff(second, timestampadd(year,1, time1), time1)) as ab\n" + "  from tdvt.calcs as calcs group by ab order by ab ) tmp";
    ccSql = //
    "select sum(tmp.ab) from (\n" + //
    "  select sum(CALCS.CC_AUTO_18) as ab\n" + "  from tdvt.calcs as calcs group by ab order by ab ) tmp";
    check(converter, originSql, ccSql, "tdvt");
    // case 9
    originSql = "select sum(timestampdiff(minute, time1, time0)), datetime0, time1, time0\n" + //
    "from tdvt.calcs group by datetime0, time1, time0\n" + //
    "union\n" + "select max(timestampdiff(minute, time1, time0)), datetime0, time1, time0\n" + "from tdvt.calcs group by datetime0, time1, time0";
    ccSql = "select sum(CALCS.CC_AUTO_9), datetime0, time1, time0\n" + //
    "from tdvt.calcs group by datetime0, time1, time0\n" + //
    "union\n" + "select max(CALCS.CC_AUTO_9), datetime0, time1, time0\n" + "from tdvt.calcs group by datetime0, time1, time0";
    check(converter, originSql, ccSql, "tdvt");
    // case 10
    originSql = "select max(timestampdiff(second, time0, cast(datetime1 as timestamp)))\n" + //
    " - min(timestampdiff(second, time0, cast(datetime1 as timestamp)))\n" + "from tdvt.calcs";
    ccSql = //
    "select max(CALCS.CC_AUTO_17)\n" + //
    " - min(CALCS.CC_AUTO_17)\n" + "from tdvt.calcs";
    check(converter, originSql, ccSql, "tdvt");
    // case 11
    originSql = "select num1, max(TIMESTAMPADD(SQL_TSI_DAY, 1, TIMESTAMP '1970-01-01 10:01:01')) MAXTIME,\n" + "      max(TIMESTAMPADD(SQL_TSI_DAY, 1, TIMESTAMP '1970-01-01 10:01:01')) over() MAXTIME1\n" + //
    "from tdvt.calcs where num1 > 0\n" + //
    "group by num1\n" + "order by TIMESTAMPADD(SQL_TSI_DAY,1, TIMESTAMP '1970-01-01 10:01:01')";
    ccSql = "select num1, max(TIMESTAMPADD(SQL_TSI_DAY, 1, TIMESTAMP '1970-01-01 10:01:01')) MAXTIME,\n" + "      max(TIMESTAMPADD(SQL_TSI_DAY, 1, TIMESTAMP '1970-01-01 10:01:01')) over() MAXTIME1\n" + //
    "from tdvt.calcs where num1 > 0\n" + //
    "group by num1\n" + "order by TIMESTAMPADD(SQL_TSI_DAY,1, TIMESTAMP '1970-01-01 10:01:01')";
    check(converter, originSql, ccSql, "tdvt");
    // case 12
    originSql = //
    "select num1, max(TIMESTAMPADD(SQL_TSI_DAY, 1, time0)) over() MAXTIME1\n" + //
    "from tdvt.calcs\n" + //
    "where num1 > 0\n" + //
    "group by num1, time0\n" + "order by TIMESTAMPADD(SQL_TSI_DAY,1, TIMESTAMP'1970-01-01 10:01:01')";
    ccSql = //
    "select num1, max(TIMESTAMPADD(SQL_TSI_DAY, 1, time0)) over() MAXTIME1\n" + //
    "from tdvt.calcs\n" + //
    "where num1 > 0\n" + //
    "group by num1, time0\n" + "order by TIMESTAMPADD(SQL_TSI_DAY,1, TIMESTAMP'1970-01-01 10:01:01')";
    check(converter, originSql, ccSql, "tdvt");
}

@Test
public void testExplicitCcNameToInnerName() {
