    ccSql = "select max(CALCS.CC_AUTO_17)\n" + " - min(CALCS.CC_AUTO_17)\n" + "from (select CC_AUTO_17 as CC_AUTO_17  from tdvt.calcs group by CC_AUTO_17)";
    check(converter, originSql, ccSql, "tdvt");
    // case 3. explicit query CC with 'quotation marks'
    originSql = "select max(CALCS.CC_AUTO_17)\n" + " - min(\"CALCS\".\"CC_AUTO_17\")\n" + "from (select CC_AUTO_17 as CC_AUTO_17  from tdvt.calcs group by CC_AUTO_17)";
    ccSql = "select max(CALCS.CC_AUTO_17)\n" + " - min(\"CALCS\".\"CC_AUTO_17\")\n" + "from (select CC_AUTO_17 as CC_AUTO_17  from tdvt.calcs group by CC_AUTO_17)";
    check(converter, originSql, ccSql, "tdvt");
    originSql = "select max(CALCS.CC_AUTO_17)\n" + " - min(CALCS.CC_AUTO_17)\n" + "from (select \"CC_AUTO_17\" as CC_AUTO_17  from tdvt.calcs group by CC_AUTO_17)";
    ccSql = "select max(CALCS.CC_AUTO_17)\n" + " - min(CALCS.CC_AUTO_17)\n" + "from (select \"CC_AUTO_17\" as CC_AUTO_17  from tdvt.calcs group by CC_AUTO_17)";
    check(converter, originSql, ccSql, "tdvt");
    // case 4. explicit query CC with lower-case
    originSql = "select max(CALCS.CC_AUTO_17)\n" + " - min(calcs.\"CC_AUTO_17\")\n" + "from (select \"CC_AUTO_17\" as CC_AUTO_17  from tdvt.calcs group by CC_AUTO_17)";
    ccSql = "select max(CALCS.CC_AUTO_17)\n" + " - min(calcs.\"CC_AUTO_17\")\n" + "from (select \"CC_AUTO_17\" as CC_AUTO_17  from tdvt.calcs group by CC_AUTO_17)";
    check(converter, originSql, ccSql, "tdvt");
}

@Test
public void transformSumNumericLiteral() {
