    Assert.assertEquals(sqlOrderByExpected1, ConvertToComputedColumn.replaceComputedColumn(sqlOrderBy1, SqlSubqueryFinder.getSubqueries(sqlOrderBy1).get(0), mockCCs, queryAliasMatchInfo).getFirst());
    // test replacement having
