@Test
public void testRestoreComputedColumnToExprSingleTable() {
    RestoreFromComputedColumn restoreFromComputedColumn = new RestoreFromComputedColumn();
    //simple query
    {
        String ret = restoreFromComputedColumn.convert("select DEAL_AMOUNT,DEAL_YEAR from test_kylin_fact", "default", "DEFAULT");
        Assert.assertEquals("select \"TEST_KYLIN_FACT\".\"PRICE\" * \"TEST_KYLIN_FACT\".\"ITEM_COUNT\" AS DEAL_AMOUNT,year(\"TEST_KYLIN_FACT\".\"CAL_DT\") AS DEAL_YEAR from test_kylin_fact", ret);
    }
    //group by
    {
        String ret = restoreFromComputedColumn.convert("select DEAL_AMOUNT,DEAL_YEAR from test_kylin_fact group by DEAL_YEAR", "default", "DEFAULT");
        Assert.assertEquals("select \"TEST_KYLIN_FACT\".\"PRICE\" * \"TEST_KYLIN_FACT\".\"ITEM_COUNT\" AS DEAL_AMOUNT,year(\"TEST_KYLIN_FACT\".\"CAL_DT\") AS DEAL_YEAR from test_kylin_fact group by year(\"TEST_KYLIN_FACT\".\"CAL_DT\")", ret);
    }
    //order by non-alias
    {
        String ret = restoreFromComputedColumn.convert("select sum(DEAL_AMOUNT) ,cal_dt as x from test_kylin_fact group by cal_dt order by sum(DEAL_AMOUNT)", "default", "DEFAULT");
        Assert.assertEquals("select sum(\"TEST_KYLIN_FACT\".\"PRICE\" * \"TEST_KYLIN_FACT\".\"ITEM_COUNT\") ,cal_dt as x from test_kylin_fact group by cal_dt order by sum(\"TEST_KYLIN_FACT\".\"PRICE\" * \"TEST_KYLIN_FACT\".\"ITEM_COUNT\")", ret);
    }
    //order by
    {
        String ret = restoreFromComputedColumn.convert("select sum(DEAL_AMOUNT) as DEAL_AMOUNTx,cal_dt as x from test_kylin_fact group by cal_dt order by DEAL_AMOUNTx", "default", "DEFAULT");
        Assert.assertEquals("select sum(\"TEST_KYLIN_FACT\".\"PRICE\" * \"TEST_KYLIN_FACT\".\"ITEM_COUNT\") as DEAL_AMOUNTx,cal_dt as x from test_kylin_fact group by cal_dt order by DEAL_AMOUNTx", ret);
    }
    //col with alias
    {
        String ret = restoreFromComputedColumn.convert("select sum(\"F\".\"DEAL_AMOUNT\") as DEAL_AMOUNTx,cal_dt as x from test_kylin_fact as \"F\" group by cal_dt order by DEAL_AMOUNTx", "default", "DEFAULT");
        Assert.assertEquals("select sum(\"F\".\"PRICE\" * \"F\".\"ITEM_COUNT\") as DEAL_AMOUNTx,cal_dt as x from test_kylin_fact as \"F\" group by cal_dt order by DEAL_AMOUNTx", ret);
    }
    //col with alias, one less AS
    {
        String ret = restoreFromComputedColumn.convert("select sum(\"F\".\"DEAL_AMOUNT\") as DEAL_AMOUNTx,cal_dt as x from test_kylin_fact \"F\" group by cal_dt order by DEAL_AMOUNTx", "default", "DEFAULT");
        Assert.assertEquals("select sum(\"F\".\"PRICE\" * \"F\".\"ITEM_COUNT\") as DEAL_AMOUNTx,cal_dt as x from test_kylin_fact \"F\" group by cal_dt order by DEAL_AMOUNTx", ret);
    }
    // nested cc
    {
        String ret = restoreFromComputedColumn.convert("select NEST3 from TEST_KYLIN_FACT", "default", "DEFAULT");
        Assert.assertEquals("select round((\"TEST_KYLIN_FACT\".\"PRICE\" + 11) * 12, 0) AS NEST3 from TEST_KYLIN_FACT", ret);
    }
    // nested cc
    {
        String ret = restoreFromComputedColumn.convert("select NEST4 from TEST_KYLIN_FACT", "default", "DEFAULT");
        Assert.assertEquals("select (round((\"TEST_KYLIN_FACT\".\"PRICE\" + 11) * 12, 0)) * \"TEST_KYLIN_FACT\".\"ITEM_COUNT\" AS NEST4 from TEST_KYLIN_FACT", ret);
    }
}

