@Test
public void testCollectedFinished() {
    QueryHistoryScheduler queryHistoryScheduler = QueryHistoryScheduler.getInstance();
    String queryId = "12sy4s87-f912-6dw2-a1e1-8ff3234u2e6b1";
    long prepareAndSubmitJobMs = 10;
    long waitForExecutionMs = 200;
    long executionMs = 1200;
    long fetchResultMs = 20;
    SparkJobTraceMetric sparkJobTraceMetric = new SparkJobTraceMetric(prepareAndSubmitJobMs, waitForExecutionMs, executionMs, fetchResultMs);
    QueryMetrics queryMetrics = new QueryMetrics(queryId, "192.168.1.6:7070");
    queryMetrics.setQueryDuration(5578L);
    queryMetrics.setQueryTime(1584888338274L);
    QueryHistoryInfo queryHistoryInfo = new QueryHistoryInfo();
    List<QueryHistoryInfo.QueryTraceSpan> queryTraceSpans = new ArrayList<>();
    queryTraceSpans.add(new QueryHistoryInfo.QueryTraceSpan(QueryTrace.PREPARE_AND_SUBMIT_JOB, QueryTrace.SPAN_GROUPS.get(QueryTrace.WAIT_FOR_EXECUTION), 0));
    queryHistoryInfo.setTraces(queryTraceSpans);
    queryMetrics.setQueryHistoryInfo(queryHistoryInfo);
    Boolean isCollectedFinished = queryHistoryScheduler.isCollectedFinished(queryId, sparkJobTraceMetric, queryMetrics);
    Assert.assertTrue(isCollectedFinished);
    List<QueryHistoryInfo.QueryTraceSpan> newQueryTraceSpans = queryMetrics.getQueryHistoryInfo().getTraces();
    Assert.assertEquals(prepareAndSubmitJobMs, newQueryTraceSpans.get(0).getDuration());
    Assert.assertEquals(waitForExecutionMs, newQueryTraceSpans.get(1).getDuration());
    Assert.assertEquals(executionMs, newQueryTraceSpans.get(2).getDuration());
    Assert.assertTrue(newQueryTraceSpans.get(3).getDuration() > 0);
    queryTraceSpans = new ArrayList<>();
    queryMetrics.getQueryHistoryInfo().setTraces(queryTraceSpans);
    queryTraceSpans.add(new QueryHistoryInfo.QueryTraceSpan(QueryTrace.PREPARE_AND_SUBMIT_JOB, QueryTrace.SPAN_GROUPS.get(QueryTrace.WAIT_FOR_EXECUTION), 0));
    isCollectedFinished = queryHistoryScheduler.isCollectedFinished(queryId, null, queryMetrics);
    Assert.assertTrue(isCollectedFinished);
    newQueryTraceSpans = queryMetrics.getQueryHistoryInfo().getTraces();
    Assert.assertEquals(1, newQueryTraceSpans.size());
    queryMetrics.setQueryDuration(5000);
    queryMetrics.setQueryTime(System.currentTimeMillis());
    isCollectedFinished = queryHistoryScheduler.isCollectedFinished(queryId, null, queryMetrics);
    Assert.assertFalse(isCollectedFinished);
    Assert.assertEquals(1, queryHistoryScheduler.queryMetricsQueue.size());
}

@Test
public void testGetFilteredQueryHistories() {
    // when there is no filter conditions
    QueryHistoryRequest request = new QueryHistoryRequest();
    request.setProject(PROJECT);
    // set default values
    request.setStartTimeFrom("0");
    request.setStartTimeTo(String.valueOf(Long.MAX_VALUE));
    request.setLatencyFrom("0");
    request.setLatencyTo(String.valueOf(Integer.MAX_VALUE));
    // mock query histories
    // pushdown query
    QueryHistory pushdownQuery = new QueryHistory();
    pushdownQuery.setSql("select * from test_table_1");
    pushdownQuery.setEngineType("HIVE");
    // failed query
    QueryHistory failedQuery = new QueryHistory();
    failedQuery.setSql("select * from test_table_2");
    // accelerated query
    QueryHistory acceleratedQuery = new QueryHistory();
    acceleratedQuery.setSql("select * from test_table_3");
    QueryMetrics.RealizationMetrics metrics1 = new QueryMetrics.RealizationMetrics("1", "Agg Index", "741ca86a-1f13-46da-a59f-95fb68615e3a", Lists.newArrayList(new String[] {}));
    QueryMetrics.RealizationMetrics metrics2 = new QueryMetrics.RealizationMetrics("1", "Agg Index", "89af4ee2-2cdb-4b07-b39e-4c29856309aa", Lists.newArrayList(new String[] {}));
    QueryHistoryInfo queryHistoryInfo = new QueryHistoryInfo();
    queryHistoryInfo.setRealizationMetrics(Lists.newArrayList(new QueryMetrics.RealizationMetrics[] { metrics1, metrics2 }));
    acceleratedQuery.setQueryHistoryInfo(queryHistoryInfo);
    RDBMSQueryHistoryDAO queryHistoryDAO = Mockito.mock(RDBMSQueryHistoryDAO.class);
    Mockito.doReturn(Lists.newArrayList(pushdownQuery, failedQuery, acceleratedQuery)).when(queryHistoryDAO).getQueryHistoriesByConditions(Mockito.any(), Mockito.anyInt(), Mockito.anyInt());
    Mockito.doReturn(10L).when(queryHistoryDAO).getQueryHistoriesSize(Mockito.any(), Mockito.anyString());
    Mockito.doReturn(queryHistoryDAO).when(queryHistoryService).getQueryHistoryDao();
    Map<String, Object> result = queryHistoryService.getQueryHistories(request, 10, 0);
    List<QueryHistory> queryHistories = (List<QueryHistory>) result.get("query_histories");
    long size = (long) result.get("size");
    Assert.assertEquals(3, queryHistories.size());
    Assert.assertEquals(10, size);
    // assert pushdown query
    Assert.assertEquals(pushdownQuery.getSql(), queryHistories.get(0).getSql());
    Assert.assertEquals(pushdownQuery.getEngineType(), queryHistories.get(0).getEngineType());
    Assert.assertTrue(CollectionUtils.isEmpty(pushdownQuery.getNativeQueryRealizations()));
    // assert failed query
    Assert.assertEquals(failedQuery.getSql(), queryHistories.get(1).getSql());
    Assert.assertTrue(CollectionUtils.isEmpty(queryHistories.get(1).getNativeQueryRealizations()));
    Assert.assertNull(queryHistories.get(1).getEngineType());
    // assert accelerated query
    Assert.assertEquals(acceleratedQuery.getSql(), queryHistories.get(2).getSql());
    var modelAlias = queryHistories.get(2).getNativeQueryRealizations().stream().map(NativeQueryRealization::getModelAlias).collect(Collectors.toSet());
    Assert.assertEquals(2, modelAlias.size());
    Assert.assertTrue(modelAlias.contains("nmodel_basic"));
    Assert.assertTrue(modelAlias.contains("nmodel_basic_inner"));
    val modelIds = queryHistories.get(2).getNativeQueryRealizations().stream().map(NativeQueryRealization::getModelId).collect(Collectors.toSet());
    Assert.assertTrue(modelIds.contains("741ca86a-1f13-46da-a59f-95fb68615e3a"));
    Assert.assertTrue(modelIds.contains("89af4ee2-2cdb-4b07-b39e-4c29856309aa"));
    tableService.unloadTable(PROJECT, "DEFAULT.TEST_KYLIN_FACT", false);
    queryHistories = (List<QueryHistory>) queryHistoryService.getQueryHistories(request, 10, 0).get("query_histories");
    modelAlias = queryHistories.get(2).getNativeQueryRealizations().stream().map(NativeQueryRealization::getModelAlias).collect(Collectors.toSet());
    Assert.assertTrue(modelAlias.contains("nmodel_basic broken"));
    Assert.assertTrue(modelAlias.contains("nmodel_basic_inner broken"));
    val id = "741ca86a-1f13-46da-a59f-95fb68615e3a";
    NDataflowManager.getInstance(getTestConfig(), PROJECT).dropDataflow(id);
    NIndexPlanManager.getInstance(getTestConfig(), PROJECT).dropIndexPlan(id);
    NDataModelManager.getInstance(getTestConfig(), PROJECT).dropModel(id);
    queryHistories = (List<QueryHistory>) queryHistoryService.getQueryHistories(request, 10, 0).get("query_histories");
    modelAlias = queryHistories.get(2).getNativeQueryRealizations().stream().map(NativeQueryRealization::getModelAlias).collect(Collectors.toSet());
    Assert.assertTrue(modelAlias.contains(QueryHistoryService.DELETED_MODEL));
}

