@Test
public void testTransformNode() throws IOException {
    ClusterInfo cluster = new ClusterInfo().setKeepAliveTimeout("600000").setSocketTimeout("600000");
    Map<String, List<Node>> clusterNode = new HashMap<>();
    clusterNode.put("pair0", Lists.newArrayList(new Node("node01", "127.0.0.1", 9000, "default", "", 111)));
    clusterNode.put("pair1", Lists.newArrayList(new Node("node02", "127.0.0.2", 9000, "default", "")));
    cluster.setCluster(clusterNode);
    cluster.transformNode();
    int size = cluster.getNodes().stream().filter(node -> {
        return node.getSSHPort() == 22;
    }).collect(Collectors.toList()).size();
    Assert.assertEquals(1, size);
    size = cluster.getNodes().stream().filter(node -> {
        return node.getSSHPort() == 111;
    }).collect(Collectors.toList()).size();
    Assert.assertEquals(1, size);
    File file = File.createTempFile("clickhouseTemp", ".yaml");
    ClickHouseConfigLoader.getConfigYaml().dump(JsonUtil.readValue(JsonUtil.writeValueAsString(cluster), Map.class), new PrintWriter(file, Charset.defaultCharset().name()));
    overwriteSystemProp(CONFIG_SECOND_STORAGE_CLUSTER, file.getAbsolutePath());
    ClusterInfo clusterReader = ClickHouseConfigLoader.getInstance().getCluster();
    List<Node> allNodes = clusterReader.getNodes();
    int portSize = allNodes.stream().filter(node -> {
        return node.getSSHPort() == 22;
    }).collect(Collectors.toList()).size();
    Assert.assertEquals(1, portSize);
    portSize = allNodes.stream().filter(node -> {
        return node.getSSHPort() == 111;
    }).collect(Collectors.toList()).size();
    Assert.assertEquals(1, portSize);
}

@SuppressWarnings("unchecked")
@Test
public void testCRUD() throws NoSuchMethodException, IllegalAccessException, InvocationTargetException, InstantiationException {
    KylinConfig config = KylinConfig.getInstanceFromEnv();
    Manager<TableFlow> manager = SecondStorage.tableFlowManager(config, DEFAULT_PROJECT);
    Assert.assertNotNull(manager);
    // refect
    Class<? extends Manager<TableFlow>> managerClass = (Class<? extends Manager<TableFlow>>) manager.getClass();
    Constructor<? extends Manager<TableFlow>> constructor = managerClass.getDeclaredConstructor(KylinConfig.class, String.class);
    Unsafe.changeAccessibleObject(constructor, true);
    final Manager<TableFlow> refectionManage = constructor.newInstance(config, DEFAULT_PROJECT);
    Assert.assertNotNull(refectionManage);
    final String cubeName = RandomUtil.randomUUIDStr();
    TableFlow flow = TableFlow.builder().setModel(cubeName).setDescription(TEST_DESCRIPTION).build();
    Assert.assertNotNull(manager.createAS(flow));
    // list
    List<TableFlow> flows = manager.listAll();
    Assert.assertEquals(1, flows.size());
    // get
    TableFlow flow2 = manager.get(cubeName).orElse(null);
    Assert.assertNotNull(flow2);
    // update
    try {
        flow2.setDescription("new_description");
        Assert.fail();
    } catch (IllegalStateException ex) {
        // expected for updating the cached object
    }
    TableFlow flow3 = manager.update(flow.getUuid(), copyForWrite -> copyForWrite.setDescription("new_description"));
    Assert.assertEquals("new_description", flow3.getDescription());
    // delete
    manager.delete(flow);
    TableFlow flow4 = manager.get(cubeName).orElse(null);
    Assert.assertNull(flow4);
    Assert.assertEquals(0, manager.listAll().size());
}

