public void testSkippingIndexType() {
    assertEquals(SkippingIndexType.MINMAX, SkippingIndexChooser.getSkippingIndexType(new DataType(DataType.INTEGER, 0, 0)));
    assertEquals(SkippingIndexType.MINMAX, SkippingIndexChooser.getSkippingIndexType(new DataType(DataType.TINY_INT, 0, 0)));
    assertEquals(SkippingIndexType.MINMAX, SkippingIndexChooser.getSkippingIndexType(new DataType(DataType.BIGINT, 0, 0)));
    assertEquals(SkippingIndexType.MINMAX, SkippingIndexChooser.getSkippingIndexType(new DataType(DataType.SMALL_INT, 0, 0)));
    assertEquals(SkippingIndexType.SET, SkippingIndexChooser.getSkippingIndexType(new DataType(DataType.BOOLEAN, 0, 0)));
    assertEquals(SkippingIndexType.BLOOM_FILTER, SkippingIndexChooser.getSkippingIndexType(new DataType(DataType.VARCHAR, 0, 0)));
    assertEquals(SkippingIndexType.BLOOM_FILTER, SkippingIndexChooser.getSkippingIndexType(new DataType(DataType.STRING, 0, 0)));
    DataType real = new DataType(DataType.REAL, 0, 0);
    assertThrows(KylinException.class, () -> SkippingIndexChooser.getSkippingIndexType(real));
    System.setProperty("kylin.second-storage.skipping-index.set", "101");
    assertEquals("bloom_filter(0.025)", SkippingIndexType.BLOOM_FILTER.toSql(getConfig()));
    assertEquals("set(101)", SkippingIndexType.SET.toSql(getConfig()));
    System.setProperty("kylin.second-storage.skipping-index.bloom-filter", "0.5");
    assertEquals("bloom_filter(0.5)", SkippingIndexType.BLOOM_FILTER.toSql(getConfig()));
    assertEquals("minmax()", SkippingIndexType.MINMAX.toSql(getConfig()));
}

