            {
                long layoutId = getDataFlow().getIndexPlan().getBaseTableLayoutId();
                List<Integer> rowsList = getHAModelRowCount(getProject(), modelId, layoutId, new JdbcDatabaseContainer[] { clickhouse1, clickhouse3 });
                Assert.assertEquals(1, rowsList.stream().distinct().count());
                rowsList = getHAModelRowCount(getProject(), modelId, layoutId, new JdbcDatabaseContainer[] { clickhouse2, clickhouse4 });
                Assert.assertEquals(1, rowsList.stream().distinct().count());
            }
            String sql = "select CAL_DT from TEST_KYLIN_FACT where CAL_DT between '2012-01-01' and '2012-01-02'";
            Map<String, Map<String, Boolean>> nodeStatusMap;
            {
                // all live
                clearQueryContext();
                ExecAndComp.queryModel(getProject(), sql);
                Assert.assertTrue(OLAPContext.getNativeRealizations().stream().allMatch(NativeQueryRealization::isSecondStorage));
            }
            {
                // all group down
                clearQueryContext();
                nodeStatusMap = ImmutableMap.of("pair0", ImmutableMap.of("node00", false, "node02", false), "pair1", ImmutableMap.of("node01", false, "node03", false));
                secondStorageEndpoint.updateNodeStatus(nodeStatusMap);
                ExecAndComp.queryModel(getProject(), sql);
                Assert.assertTrue(OLAPContext.getNativeRealizations().stream().noneMatch(NativeQueryRealization::isSecondStorage));
            }
            {
                // different group down
                clearQueryContext();
                nodeStatusMap = ImmutableMap.of("pair0", ImmutableMap.of("node00", false, "node02", true), "pair1", ImmutableMap.of("node01", false, "node03", true));
                secondStorageEndpoint.updateNodeStatus(nodeStatusMap);
                clearQueryContext();
                ExecAndComp.queryModel(getProject(), sql);
                Assert.assertTrue(OLAPContext.getNativeRealizations().stream().allMatch(NativeQueryRealization::isSecondStorage));
            }
            {
                // same group down
                clearQueryContext();
                nodeStatusMap = ImmutableMap.of("pair0", ImmutableMap.of("node00", true, "node02", false), "pair1", ImmutableMap.of("node01", false, "node03", true));
                secondStorageEndpoint.updateNodeStatus(nodeStatusMap);
                ExecAndComp.queryModel(getProject(), sql);
                Assert.assertTrue(OLAPContext.getNativeRealizations().stream().anyMatch(NativeQueryRealization::isSecondStorage));
            }
            {
                // down one shard
                clearQueryContext();
                nodeStatusMap = ImmutableMap.of("pair0", ImmutableMap.of("node00", false, "node02", false), "pair1", ImmutableMap.of("node01", true, "node03", true));
                secondStorageEndpoint.updateNodeStatus(nodeStatusMap);
                ExecAndComp.queryModel(getProject(), sql);
                Assert.assertTrue(OLAPContext.getNativeRealizations().stream().noneMatch(NativeQueryRealization::isSecondStorage));
            }
            {
                nodeStatusMap = ImmutableMap.of("pair0", ImmutableMap.of("node00", false, "node02", true), "pair1", ImmutableMap.of("node01", true, "node03", true));
                secondStorageEndpoint.updateNodeStatus(nodeStatusMap);
                assertEquals("000", secondStorageEndpoint.tableSync(getProject()).getCode());
                getTableFlow().getTableDataList().forEach(tableData -> tableData.getPartitions().forEach(partition -> {
                    assertEquals(2, partition.getShardNodes().size());
                    if (partition.getShardNodes().contains("node00")) {
                        assertEquals(0L, partition.getSizeInNode().get("node00").longValue());
                    }
                }));
            }
            {
                val lock1 = new ProjectLockOperateRequest();
                lock1.setProject(getProject());
                lock1.setLockTypes(Arrays.asList(LockTypeEnum.LOAD.name(), LockTypeEnum.QUERY.name()));
                lock1.setOperateType(LockOperateTypeEnum.LOCK.name());
                ClickHouseSimpleITTestUtils.checkLockOperateResult(secondStorageEndpoint.lockOperate(lock1), Arrays.asList(LockTypeEnum.LOAD.name(), LockTypeEnum.QUERY.name()), getProject());
                val lock2 = new ProjectLockOperateRequest();
                lock2.setProject(getProject());
                lock2.setLockTypes(Collections.singletonList(LockTypeEnum.LOAD.name()));
                lock2.setOperateType(LockOperateTypeEnum.UNLOCK.name());
                ClickHouseSimpleITTestUtils.checkLockOperateResult(secondStorageEndpoint.lockOperate(lock2), Collections.singletonList(LockTypeEnum.QUERY.name()), getProject());
                secondStorageService.sizeInNode(getProject());
                val lock3 = new ProjectLockOperateRequest();
                lock3.setProject(getProject());
                lock3.setLockTypes(Collections.singletonList(LockTypeEnum.QUERY.name()));
                lock3.setOperateType(LockOperateTypeEnum.UNLOCK.name());
                ClickHouseSimpleITTestUtils.checkLockOperateResult(secondStorageEndpoint.lockOperate(lock3), Collections.emptyList(), getProject());
            }
            {
                // test recover model
                val request = new RecoverRequest();
                request.setProject(getProject());
                val response = openSecondStorageEndpoint.recoverProject(request);
                Assert.assertEquals(1, response.getData().getSubmittedModels().size());
                Assert.assertEquals(0, response.getData().getFailedModels().size());
            }
            //reset status
            nodeStatusMap = ImmutableMap.of("pair0", ImmutableMap.of("node00", true, "node02", true), "pair1", ImmutableMap.of("node01", true, "node03", true));
            secondStorageEndpoint.updateNodeStatus(nodeStatusMap);
            return true;
        });
    }
}

