        System.out.println(processors.stream().map(EnvironmentPostProcessor::getClass).map(Class::getSimpleName).collect(Collectors.joining(",")));
        Map<? extends Class<? extends EnvironmentPostProcessor>, Integer> classIndexMap = processors.stream().collect(Collectors.toMap(EnvironmentPostProcessor::getClass, processors::indexOf));
        Integer configDataEnvIndex = classIndexMap.get(ConfigDataEnvironmentPostProcessor.class);
        Integer kylinPrepareEnvIndex = classIndexMap.get(KylinPrepareEnvListener.class);
        Integer kylinPropertySourceIndex = classIndexMap.get(KylinPropertySourceConfiguration.class);
