@Test
public void testBasic() throws IOException {
    ISource source = SourceFactory.getSource(new ISourceAware() {

        @Override
        public int getSourceType() {
            return ISourceAware.ID_JDBC;
        }

        @Override
        public KylinConfig getConfig() {
            return getTestConfig();
        }
    });
    ISourceMetadataExplorer metadataExplorer = source.getSourceMetadataExplorer();
    ISampleDataDeployer sampleDataDeployer = source.getSampleDataDeployer();
    Assert.assertTrue(source instanceof JdbcSource);
    Assert.assertTrue(metadataExplorer instanceof JdbcExplorer);
    Assert.assertTrue(sampleDataDeployer instanceof JdbcExplorer);
    NSparkCubingEngine.NSparkCubingSource cubingSource = source.adaptToBuildEngine(NSparkCubingEngine.NSparkCubingSource.class);
    Assert.assertTrue(cubingSource instanceof JdbcSourceInput);
    NTableMetadataManager tableMgr = NTableMetadataManager.getInstance(getTestConfig(), "ssb");
    TableDesc tableDesc = tableMgr.getTableDesc("SSB.PART");
    IReadableTable readableTable = source.createReadableTable(tableDesc);
    Assert.assertTrue(readableTable instanceof JdbcTable);
    IReadableTable.TableReader reader = readableTable.getReader();
    Assert.assertTrue(reader instanceof JdbcTableReader);
    Assert.assertTrue(readableTable.exists());
    Assert.assertNotNull(readableTable.getSignature());
    while (reader.next()) {
        String[] row = reader.getRow();
        Assert.assertNotNull(row);
    }
    reader.close();
    SegmentRange segmentRange = source.getSegmentRange("0", "21423423");
    Assert.assertTrue(segmentRange instanceof SegmentRange.TimePartitionedSegmentRange && segmentRange.getStart().equals(0L) && segmentRange.getEnd().equals(21423423L));
    SegmentRange segmentRange2 = source.getSegmentRange("", "");
    Assert.assertTrue(segmentRange2 instanceof SegmentRange.TimePartitionedSegmentRange && segmentRange2.getStart().equals(0L) && segmentRange2.getEnd().equals(Long.MAX_VALUE));
    assert !source.supportBuildSnapShotByPartition();
    source.close();
}

@Test
public void testCancelPushdownJob() throws InterruptedException {
    AtomicReference<SparkListenerJobEnd> sparkJobEnd = new AtomicReference<>();
    CountDownLatch isJobEnd = new CountDownLatch(1);
    ss.sparkContext().addSparkListener(new SparkListener() {

        @Override
        public void onTaskStart(SparkListenerTaskStart taskStart) {
            for (SlowQueryDetector.QueryEntry e : SlowQueryDetector.getRunningQueries().values()) {
                e.setStopByUser(true);
                e.getThread().interrupt();
                return;
            }
            Assert.fail("no running query is found");
        }

        @Override
        public void onJobEnd(SparkListenerJobEnd jobEnd) {
            sparkJobEnd.set(jobEnd);
            isJobEnd.countDown();
        }
    });
    Thread queryThread = new Thread(() -> {
        try {
            slowQueryDetector.queryStart("foo");
            String sql = "select * from TEST_KYLIN_FACT";
            SparkSqlClient.executeSql(ss, sql, RandomUtil.randomUUID(), "tpch");
        } catch (Exception e) {
            Assert.assertTrue(e instanceof UserStopQueryException);
        } finally {
            slowQueryDetector.queryEnd();
        }
    });
    queryThread.start();
    queryThread.join();
    isJobEnd.await(10, TimeUnit.SECONDS);
    Assert.assertTrue(sparkJobEnd.get().jobResult() instanceof JobFailed);
    Assert.assertTrue(((JobFailed) sparkJobEnd.get().jobResult()).exception().getMessage().contains("cancelled part of cancelled job group"));
}

