        Assert.assertEquals(5, df.getSegments().size());
        Assert.assertEquals("1", df.getSegment(mergeJobEntry.afterMergeSegment().getId()).getAdditionalInfo().get("file_layer"));
    } catch (Exception e) {
        logger.error(e.getMessage(), e);
    }
}

