    getTestConfig().clearManagers();
    ResourceStore.clearCache();
    executableManager = NExecutableManager.getInstance(getTestConfig(), "version40");
    executeJobs = executableManager.getAllExecutables().stream().filter(executable -> JobTypeEnum.INC_BUILD == executable.getJobType() || JobTypeEnum.INDEX_BUILD == executable.getJobType() || JobTypeEnum.INDEX_REFRESH == executable.getJobType() || JobTypeEnum.SUB_PARTITION_REFRESH == executable.getJobType() || JobTypeEnum.INDEX_MERGE == executable.getJobType()).filter(executable -> ExecutableState.RUNNING == executable.getStatus() || ExecutableState.ERROR == executable.getStatus() || ExecutableState.PAUSED == executable.getStatus()).collect(Collectors.toList());
    Assert.assertEquals(1, executeJobs.size());
    for (AbstractExecutable executeJob : executeJobs) {
        val job = (DefaultExecutableOnModel) executeJob;
        Assert.assertEquals(3, job.getTasks().size());
        switch(job.getJobType()) {
            case INDEX_BUILD:
                Assert.assertEquals("org.apache.kylin.engine.spark.job.ExecutableAddCuboidHandler", job.getHandler().getClass().getName());
                break;
            case INC_BUILD:
                Assert.assertEquals("org.apache.kylin.engine.spark.job.ExecutableAddSegmentHandler", job.getHandler().getClass().getName());
                break;
            case INDEX_REFRESH:
            case SUB_PARTITION_REFRESH:
            case INDEX_MERGE:
                Assert.assertEquals("org.apache.kylin.engine.spark.job.ExecutableMergeOrRefreshHandler", job.getHandler().getClass().getName());
                break;
            default:
                break;
        }
    }
}

